<script setup lang="ts">import {computed} from 'vue';import Table from './common/Table.vue';const p=defineProps<{grouping?:any}>();const normalized=computed(()=>p.grouping||{resampling_unit:'specimen',core_count:0,specimen_count:0,core_groups:[],group_sizes:[],unequal_group_sizes:false,min_group_size:null,max_group_size:null}),groups=computed<any[]>(()=>normalized.value.core_groups||[]),sizes=computed<string>(()=>[...new Set(normalized.value.group_sizes||[])].sort((a:number,b:number)=>a-b).join(' / '));</script><template><section class="section core-grouping"><div class="section-head"><h2>{{normalized.resampling_unit==='core_cluster'?'按岩芯成组，组内试样不拆开。':'旧数据无岩芯字段，逐试样分析。'}}</h2><span>{{normalized.core_count}} 岩芯 / {{normalized.specimen_count}} 试样<span v-if="normalized.unequal_group_sizes"> · 组大小不等（{{normalized.min_group_size}}–{{normalized.max_group_size}}）</span></span></div><p v-if="normalized.resampling_unit==='core_cluster'">同一岩芯切出的试样不独立。重采样以整芯为单位，每次有放回抽原数量的岩芯，携带全部试样；重复抽中的岩芯按倍数保留。点估计仍按原逐票的每个试样行等权，不按组大小加权。组大小 {{sizes}}。缺失岩芯或不足两组会被拒绝；退化重复不补抽。区间门槛沿用有效比例≥90%。</p><p v-else>本底稿没有岩芯字段，沿用逐试样重采样，不推断不存在的分组。其余口径不变。</p><details v-if="groups.length"><summary>核对岩芯分组与试样归属</summary><Table :headers="['岩芯','试样数','试样编号']"><tr v-for="g in groups" :key="g.core"><td><strong>{{g.core}}</strong></td><td>{{g.specimen_count}}</td><td>{{g.specimen_references.join('、')}}</td></tr></Table></details><div v-else class="snapshot-line">无岩芯分组；每次抽取整试样行。</div></section></template>
